                            <span class="dot"></span>
                        </div>
                    </div>
                </li>
                <li>
                    <div class="card">
                        <div class="title">
                            <p>タイトルテキストタイトルテキスト</p>
                        </div>
                        <div class="text">
                            <p>テキストテキストテキストテキストテキストテキストテキストテキストテキストテキストテキストテキストテキストテキストテキスト</p>
                        </div>
                        <div class="button">
                            <span class="dot"></span>
                        </div>
                    </div>
